from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Button, Color, Direction, Port, Stop
from pybricks.pupdevices import ColorDistanceSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up all devices.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.Y, broadcast_channel=0, observe_channels=[1])
sensor = ColorDistanceSensor(Port.E)
sensor_2 = ColorDistanceSensor(Port.F)
Left_motor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right_Motor = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left_motor, Right_Motor, 62, 80)
Left_Attachment = Motor(Port.C, Direction.CLOCKWISE)
Right_Attachment = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
Current_Program = 0
Straight_Speed = 800
Turn_Speed = 500
Attachment_Speed = 1000

async def mission__5():
    await wait(0)
    # key flip and removal attachment 1 - Block 11
    await Right_Attachment.run_angle(300, 90)
    await drive_base.straight(675)
    await drive_base.straight(0)
    await drive_base.straight(0)
    await drive_base.straight(-675)
    await drive_base.straight(0)
    await drive_base.straight(0)

async def Mission__4():
    await wait(0)
    # Salvage operation
    # 5 away on the right of the left side
    drive_base.reset(0, 0)
    await Right_Attachment.run_angle(300, 30)
    await drive_base.straight(550)
    await drive_base.straight(-60)
    Right_Attachment.reset_angle(0)
    await Right_Attachment.run_angle(500, -150)
    await drive_base.straight(-500)

async def subtask():
    await Right_Attachment.run_angle(500, -5)
    Right_Attachment.reset_angle(0)
    Left_Attachment.reset_angle(0)

async def Mission__2():
    await wait(0)
    # Double Cart Flip
    drive_base.reset(0, 0)
    await multitask(
        Left_Attachment.run_angle(500, 5),
        subtask(),
    )
    await multitask(
        Right_Attachment.run_angle(500, -120),
        Left_Attachment.run_angle(500, 120),
    )
    await drive_base.straight(753)
    await drive_base.turn(90)
    await drive_base.straight(180)
    drive_base.reset(0, 0)
    await Left_Attachment.run_angle(500, -120)
    await drive_base.straight(45)
    await multitask(
        Right_Attachment.run_angle(500, 120),
    )
    await wait(100)
    await drive_base.straight(140)
    # lift whale
    await drive_base.turn(-30)
    await Right_Attachment.run_angle(5000, -150)
    await drive_base.turn(30)
    # minecart drive
    await drive_base.straight(-20)
    await Left_Attachment.run_angle(5000, 120)
    await wait(100)
    await drive_base.straight(-10)
    await Left_Attachment.run_angle(5000, 120)
    await wait(0)
    # go home
    await drive_base.straight(-400)
    await drive_base.turn(-90)
    await drive_base.straight(-700)

async def mission__3():
    await wait(0)
    # sending stuff to the forum
    drive_base.reset(0, 0)
    await drive_base.straight(250)
    drive_base.reset(0, 0)
    await drive_base.turn(55)
    await drive_base.straight(210)
    await multitask(
        Left_Attachment.run_angle(400, 75),
        Right_Attachment.run_angle(400, -75),
    )
    await drive_base.straight(-210)
    drive_base.reset(0, 0)
    await drive_base.turn(-55)
    drive_base.reset(0, 0)
    await drive_base.straight(-300)

async def Mission_7():
    await wait(0)
    drive_base.reset(0, 0)
    await Left_Attachment.run_angle(300, -100)

